INSERT INTO dump_descriptions (base_key, description) VALUES ('cheatmanager', 'Enables the game’s Cheat Manager for Sandbox testing by attaching it to the local player controller.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('fixmacteraprojectiletrailnotshowing', 'Restores visible projectile trails removed by particle-removal mods, helping track Mactera shots and judge their trajectories.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
